// ── independent float64 recomputation (shifted-Chebyshev basis) ──────────────
// The frozen reference above was computed in the POWER basis at mpmath 50 dps.
// Everything below recomputes the same span-invariant quantities in float64
// with a DIFFERENT basis; agreement is both a numerical and a basis-
// independence cross-check.
const U = IMP95217_PRIMES.map((p) => Math.log(p) / Math.log(97));

function buildMomentSystem() {
  const a = U[0];
  const b = U[NP - 1];
  const cols = [];
  for (let i = 0; i < NM; i++) cols.push(new Float64Array(NP));
  for (let j = 0; j < NP; j++) {
    const t = (2 * (U[j] - a)) / (b - a) - 1;
    let tm = 1;
    let tc = t;
    cols[0][j] = 1;
    if (NM > 1) cols[1][j] = t;
    for (let i = 2; i < NM; i++) {
      const tn = 2 * t * tc - tm;
      cols[i][j] = tn;
      tm = tc;
      tc = tn;
    }
  }
  const dot = (u, v) => {
    let s = 0;
    for (let j = 0; j < NP; j++) s += u[j] * v[j];
    return s;
  };
  const phis = [];
  for (let i = 0; i < NM; i++) {
    const v = Float64Array.from(cols[i]);
    for (let pass = 0; pass < 2; pass++) {
      for (const q of phis) {
        const s = dot(q, v);
        for (let j = 0; j < NP; j++) v[j] -= s * q[j];
      }
    }
    const nrm = Math.sqrt(dot(v, v));
    for (let j = 0; j < NP; j++) v[j] /= nrm;
    phis.push(v);
  }
  let gramErr = 0;
  for (let x = 0; x < NM; x++)
    for (let y = 0; y < NM; y++)
      gramErr = Math.max(gramErr, Math.abs(dot(phis[x], phis[y]) - (x === y ? 1 : 0)));
  return { phis, gramErr };
}
const SYS = buildMomentSystem();
const K_DIAG = new Float64Array(NP);
{
  for (let j = 0; j < NP; j++) {
    let s = 0;
    for (let i = 0; i < NM; i++) s += SYS.phis[i][j] * SYS.phis[i][j];
    K_DIAG[j] = s;
  }
}
const K_TRACE = K_DIAG.reduce((s, x) => s + x, 0);
const K_MAX = Math.max(...K_DIAG);
const K_ARGMAX_PRIME = IMP95217_PRIMES[K_DIAG.indexOf(K_MAX)];

// cyclic Jacobi eigenvalues of a small symmetric matrix (18x18)
function jacobiEigenvalues(Ain, n) {
  const A = Ain.map((row) => Float64Array.from(row));
  for (let sweep = 0; sweep < 60; sweep++) {
    let off = 0;
    for (let p = 0; p < n - 1; p++) for (let q = p + 1; q < n; q++) off += A[p][q] * A[p][q];
    if (off < 1e-30) break;
    for (let p = 0; p < n - 1; p++) {
      for (let q = p + 1; q < n; q++) {
        if (Math.abs(A[p][q]) < 1e-300) continue;
        const theta = (A[q][q] - A[p][p]) / (2 * A[p][q]);
        const t = Math.sign(theta) / (Math.abs(theta) + Math.sqrt(theta * theta + 1)) || 1 / (theta + Math.sqrt(theta * theta + 1));
        const c = 1 / Math.sqrt(t * t + 1);
        const s = t * c;
        for (let k = 0; k < n; k++) {
          const akp = A[k][p];
          const akq = A[k][q];
          A[k][p] = c * akp - s * akq;
          A[k][q] = s * akp + c * akq;
        }
        for (let k = 0; k < n; k++) {
          const apk = A[p][k];
          const aqk = A[q][k];
          A[p][k] = c * apk - s * aqk;
          A[q][k] = s * apk + c * aqk;
        }
      }
    }
  }
  const ev = [];
  for (let i = 0; i < n; i++) ev.push(A[i][i]);
  return ev.sort((x, y) => x - y);
}

function analyzePoint(pt) {
  // reorder defects to ascending primes: gate2 emits descending 97..2
  const Dre = new Float64Array(NP);
  const Dim = new Float64Array(NP);
  for (let j = 0; j < NP; j++) {
    Dre[j] = pt.D[24 - j][0];
    Dim[j] = pt.D[24 - j][1];
  }
  // compressed Weil-form analog A = Phi diag(Re D) Phi^T
  const A = [];
  for (let x = 0; x < NM; x++) A.push(new Float64Array(NM));
  for (let x = 0; x < NM; x++)
    for (let y = x; y < NM; y++) {
      let s = 0;
      for (let j = 0; j < NP; j++) s += Dre[j] * SYS.phis[x][j] * SYS.phis[y][j];
      A[x][y] = s;
      A[y][x] = s;
    }
  const ev = jacobiEigenvalues(A, NM);
  const emax = Math.max(...ev.map(Math.abs));
  const tol = emax * 1e-10;
  let nneg = 0;
  let npos = 0;
  for (const e of ev) {
    if (e < -tol) nneg++;
    else if (e > tol) npos++;
  }
  // mode coefficients c = Phi D (complex)
  const cre = new Float64Array(NM);
  const cim = new Float64Array(NM);
  for (let i = 0; i < NM; i++) {
    let sr = 0;
    let si = 0;
    for (let j = 0; j < NP; j++) {
      sr += SYS.phis[i][j] * Dre[j];
      si += SYS.phis[i][j] * Dim[j];
    }
    cre[i] = sr;
    cim[i] = si;
  }
  let cn2 = 0;
  for (let i = 0; i < NM; i++) cn2 += cre[i] * cre[i] + cim[i] * cim[i];
  const cNorm = Math.sqrt(cn2);
  let qPure = 0;
  for (let j = 0; j < NP; j++) {
    let ipr = 0;
    let ipi = 0;
    for (let i = 0; i < NM; i++) {
      ipr += cre[i] * SYS.phis[i][j];
      ipi += cim[i] * SYS.phis[i][j];
    }
    const v = Math.hypot(ipr, ipi) / cNorm;
    if (v > qPure) qPure = v;
  }
  return { nneg, nzero: NM - nneg - npos, npos, qPure, cNorm, cre, cim, eigMin: ev[0], eigMax: ev[NM - 1] };
}

const RECOMPUTED = IMP95217_SEAM_DEFECTS.map(analyzePoint);

// ensemble mode density rho = sum_k c_k c_k^dagger / sum_k ||c_k||^2 (Hermitian)
function rhoLambdaMax() {
  const Rre = [];
  const Rim = [];
  for (let x = 0; x < NM; x++) {
    Rre.push(new Float64Array(NM));
    Rim.push(new Float64Array(NM));
  }
  let tot = 0;
  for (const r of RECOMPUTED) tot += r.cNorm * r.cNorm;
  for (const r of RECOMPUTED)
    for (let x = 0; x < NM; x++)
      for (let y = 0; y < NM; y++) {
        // rho_xy = c_x conj(c_y) / tot
        Rre[x][y] += (r.cre[x] * r.cre[y] + r.cim[x] * r.cim[y]) / tot;
        Rim[x][y] += (r.cim[x] * r.cre[y] - r.cre[x] * r.cim[y]) / tot;
      }
  let trace = 0;
  for (let x = 0; x < NM; x++) trace += Rre[x][x];
  // complex power iteration for lambda_max of the Hermitian PSD rho
  let vr = new Float64Array(NM).fill(1 / Math.sqrt(NM));
  let vi = new Float64Array(NM);
  let lam = 0;
  for (let it = 0; it < 800; it++) {
    const wr = new Float64Array(NM);
    const wi = new Float64Array(NM);
    for (let x = 0; x < NM; x++) {
      let sr = 0;
      let si = 0;
      for (let y = 0; y < NM; y++) {
        sr += Rre[x][y] * vr[y] - Rim[x][y] * vi[y];
        si += Rre[x][y] * vi[y] + Rim[x][y] * vr[y];
      }
      wr[x] = sr;
      wi[x] = si;
    }
    let n2 = 0;
    for (let x = 0; x < NM; x++) n2 += wr[x] * wr[x] + wi[x] * wi[x];
    const n = Math.sqrt(n2);
    for (let x = 0; x < NM; x++) {
      vr[x] = wr[x] / n;
      vi[x] = wi[x] / n;
    }
    lam = n; // ||rho v|| -> lambda_max for PSD rho with normalized v
  }
  return { trace, lambdaMax: lam };
}
